def is_nested(string):
    open_brackets = 0
    has_nested = False

    for char in string:
        if char == '[':
            open_brackets += 1
        elif char == ']':
            if open_brackets > 0:
                open_brackets -= 1
                if open_brackets > 0:
                    has_nested = True

    return has_nested

